_MAP_B64 = ""
_FLAGS_B64 = ""
MAP_BYTES = base64.b64decode(_MAP_B64)
TILE_FLAGS = base64.b64decode(_FLAGS_B64)

def map_tile(x: int, y: int) -> int:
    if x < 0 or y < 0 or x >= 128 or y >= 32:
        return 0
    return MAP_BYTES[y * 128 + x]

def tile_has_flag(tile: int, flag_idx: int) -> bool:
    if tile < 0 or tile >= 256:
        return False
    return bool(TILE_FLAGS[tile] & (1 << flag_idx))